import {componentDefinitions,objectComponents} from './scene-components.js';
export function prefabComponents(object){if(object.components===undefined){objectComponents(object);object.components.forEach((c,i)=>c.id=c.type+'_'+i);}return object.components;}
const safeKey=k=>(typeof k==='string'||Number.isInteger(k))&&!['__proto__','prototype','constructor'].includes(String(k));
export function validPrefabExtension(data){return (data.reparented===undefined||Array.isArray(data.reparented)&&data.reparented.length<=100000&&new Set(data.reparented.map(o=>o?.object)).size===data.reparented.length&&data.reparented.every(o=>o&&typeof o.object==='string'&&o.object&&typeof o.parent==='string'&&o.parent&&o.object!==o.parent))&& (data.additions===undefined||Array.isArray(data.additions)&&data.additions.every(o=>o&&typeof o==='object'&&!Array.isArray(o)&&typeof o.id==='string'&&o.id&&!o.prefabLink)&&new Set(data.additions.map(o=>o.id)).size===data.additions.length)&& (data.parent===undefined||typeof data.parent==='string'&&(!data.parent||/^Assets\/.+\.hbprefab\.json$/.test(data.parent))&&!data.parent.includes('..'))&&(data.removed===undefined||Array.isArray(data.removed)&&data.removed.every(id=>typeof id==='string'))&&(data.overrides===undefined||Array.isArray(data.overrides)&&data.overrides.length<=100000&&data.overrides.every(o=>typeof o?.object==='string'&&Array.isArray(o.path)&&o.path.length>0&&o.path.length<=32&&o.path.every(safeKey)&&!['id','parent','parentId'].includes(o.path[0])&&(o.remove===true||Object.hasOwn(o,'value'))&&(o.remove===undefined||typeof o.remove==='boolean')));}
export function setPrefabOverride(data,object,path,value,{remove=false}={}){const override={object,path,...remove?{remove:true}:{value:structuredClone(value)}};if(!validPrefabExtension({...data,overrides:[override]}))throw Error('프리팹 오버라이드 경로 오류');data.overrides??=[];const index=data.overrides.findIndex(o=>o.object===object&&JSON.stringify(o.path)===JSON.stringify(path));if(index<0)data.overrides.push(override);else data.overrides[index]=override;return data;}
export function revertPrefabOverride(data,object,path){data.overrides=(data.overrides||[]).filter(o=>!(o.object===object&&JSON.stringify(o.path)===JSON.stringify(path)));return data;}
export function prefabDocumentRows(data){const additions=data.additions||[],rows=[...data.objects,...additions],ids=new Set(rows.map(o=>o.id)),added=new Set(additions.map(o=>o.id));return rows.map(o=>{const next={...o};if((data.parent||added.has(o.id))&&!ids.has(o.parent||o.parentId)){delete next.parent;delete next.parentId;}return next;});}
export async function resolvePrefab(path,read,{validate,stack=[]}={}){
  if(stack.includes(path)||stack.length>=16)throw Error('프리팹 상속·중첩 순환: '+[...stack,path].join(' → '));const data=structuredClone(await read(path));if(!validPrefabExtension(data)||validate&&!validate(data))throw Error('프리팹 검증 실패: '+path);const chain=[...stack,path],inherited=data.parent?await resolvePrefab(data.parent,read,{validate,stack:chain}):null;let objects=structuredClone(inherited?.objects||[]);const expanded=new Map(inherited?.resolvedAnchors||[]);
  for(const object of data.objects||[]){const previous=objects.find(o=>o.id===object.id);if(previous?.nestedPrefab&&expanded.has(object.id)&&previous.nestedPrefab!==object.nestedPrefab){objects=objects.filter(o=>!o.id.startsWith(object.id+'/'));for(const id of expanded.keys())if(id===object.id||id.startsWith(object.id+'/'))expanded.delete(id);}const index=objects.findIndex(o=>o.id===object.id);if(index>=0)objects[index]=object;else objects.push(object);}
  for(const object of data.additions||[]){if(objects.some(o=>o.id===object.id))throw Error('추가 프리팹 오브젝트 ID가 원본과 겹쳐요: '+object.id);objects.push(object);}
  const removed=new Set(data.removed||[]),removeTrees=()=>{let count;do{count=removed.size;for(const o of objects)if(removed.has(o.parent||o.parentId))removed.add(o.id);}while(count!==removed.size);objects=objects.filter(o=>!removed.has(o.id));};removeTrees();
  const deferred=[];const apply=override=>{const owner=objects.find(o=>o.id===override.object);if(!owner)throw Error('오버라이드 대상이 없어요: '+override.object);if(override.path[0]==='components')prefabComponents(owner);let at=owner;for(const key of override.path.slice(0,-1)){at=Array.isArray(at)&&typeof key==='string'?at.find(c=>c?.id===key):at?.[key];if(!at||typeof at!=='object')throw Error('오버라이드 속성 경로가 없어요.');}if(!at||typeof at!=='object')throw Error('오버라이드 대상 속성 오류');const leaf=override.path.at(-1);if(Array.isArray(at)){const index=typeof leaf==='string'?at.findIndex(c=>c?.id===leaf):leaf;if(override.remove){if(Number.isInteger(index)&&index>=0&&index<at.length)at.splice(index,1);return;}if(typeof leaf==='string'&&index<0){if(override.value?.id!==leaf)throw Error('컴포넌트 안정 ID가 달라요.');at.push(structuredClone(override.value));}else{if(!Number.isInteger(index)||index<0||index>=at.length)throw Error('오버라이드 배열 범위를 확인하세요.');at[index]=structuredClone(override.value);}}else if(override.remove)delete at[leaf];else at[leaf]=structuredClone(override.value);};for(const override of data.overrides||[]){if(!override.object.includes('/')&&objects.some(o=>o.id===override.object))apply(override);else deferred.push(override);}
  const live=new Set(objects);for(const anchor of [...objects])if(live.has(anchor)&&anchor.nestedPrefab&&expanded.get(anchor.id)!==anchor.nestedPrefab){if(expanded.has(anchor.id)){for(const row of objects)if(row.id.startsWith(anchor.id+'/'))live.delete(row);objects=objects.filter(o=>!o.id.startsWith(anchor.id+'/'));for(const id of [...expanded.keys()])if(id===anchor.id||id.startsWith(anchor.id+'/'))expanded.delete(id);}const nested=await resolvePrefab(anchor.nestedPrefab,read,{validate,stack:chain}),ids=new Map(nested.objects.map(o=>[o.id,anchor.id+'/'+o.id]));for(const source of nested.objects){const o=structuredClone(source);o.id=ids.get(source.id);o.parent=source.id===nested.root?anchor.id:ids.get(source.parent||source.parentId);delete o.parentId;for(const key of ['owner','controller','pawn'])if(ids.has(o[key]))o[key]=ids.get(o[key]);for(const c of o.components||[])for(const [key,field] of Object.entries(componentDefinitions[c.type]?.properties||{}))if(field.objectReference&&ids.has(c.properties?.[key]))c.properties[key]=ids.get(c.properties[key]);objects.push(o);}expanded.set(anchor.id,anchor.nestedPrefab);for(const [id,asset]of nested.resolvedAnchors||[])expanded.set(anchor.id+'/'+id,asset);}
  for(const change of data.reparented||[]){const o=objects.find(o=>o.id===change.object);if(!o||!objects.some(p=>p.id===change.parent)||o.id===data.root)throw Error('프리팹 부모 오버라이드 대상이 없거나 루트예요.');o.parent=change.parent;delete o.parentId;}for(const override of deferred)apply(override);removeTrees();
  const result={...data,parent:'',objects,additions:[],overrides:[],removed:[],reparented:[],resolvedAnchors:[...expanded].filter(([id])=>objects.some(o=>o.id===id))};if(validate&&!validate(result))throw Error('프리팹 해석 결과 검증 실패: '+path);return result;
}
